9.2 分块算法 chunkText()
目标：在保持语义完整的前提下生成长度适中（≤800字符）的片段，兼容中英文。
策略：
^#{1,6}
1. 先按标题（ ）粗切
2. 对每段做长度判断，短段直接收集
/[ !? ;]\{}s*/
3. 长段再按句末标点正则 。！？ ； 分句
maxLen
4. 逐句累积至 ，超限截断换新块
核心实现（节选）：
1 export function chunkText(input: string, maxLen = 800): string[] {
2 const sections = input.split(/^#{1,6}\s+/m).map(s => s.trim()).filter(Boolean);
3 const chunks: string[] = [];
4 const push = (s: string) => { if (s.trim()) chunks.push(s.trim()); };
5 for (const sec of sections.length ? sections : [input]) {
6 if (sec.length <= maxLen) { push(sec); continue; }
7 let buf = '';
8 for (const part of sec.split(/(?<=[。！？!?；;]\s*)/)) {
9 if ((buf + part).length > maxLen) { push(buf); buf = part; }
10 else { buf += part; }
11 }
12 push(buf);
13 }
14 return chunks;
15 }
