1 function toUrlFromPath(filePath: string): { url: string; language: 'en' ￨ 'zh' } {
2 const rel = path.relative(CONTENT_DIR, filePath).replace(/\\/g, '/');
3 const noExt = rel.replace(/\.md$/i, '');
4 let cleanPath;
5 if (noExt.endsWith('/_index')) cleanPath = noExt.replace('/_index', '/');
6 else if (noExt.endsWith('/index')) cleanPath = noExt.replace('/index', '/');
7 else cleanPath = noExt + '/';
8 const language = cleanPath.startsWith('en/') ? 'en' : 'zh';
9 let finalPath;
10 if (cleanPath.startsWith('zh/blog/')) finalPath = cleanPath.replace('zh/blog/', 'blog/');
11 else if (cleanPath.startsWith('en/blog/')) finalPath = cleanPath;
12 else if (cleanPath.startsWith('zh/')) finalPath = cleanPath.replace('zh/', '');
13 else finalPath = cleanPath;
14 const urlPath = ('/' + finalPath).replace(/\/+/g, '/').replace(/\/$/, '') ￨￨ '/';
